from PIL import Image
import numpy as np
from collections import deque
im=Image.open('chess_board.png').convert('RGB'); arr=np.asarray(im).astype(int); sq=80
LIGHT=np.array([240,217,181]); DARK=np.array([181,136,99])
def bgof(f,rank):
    c=arr[(8-rank)*sq+3, f*sq+3]
    return LIGHT if np.abs(c-LIGHT).sum()<np.abs(c-DARK).sum() else DARK
def mask(f,rank,thr=80):
    ry=8-rank; bg=bgof(f,rank)
    sub=arr[ry*sq:(ry+1)*sq, f*sq:(f+1)*sq,:]
    return (np.abs(sub-bg).sum(axis=2)>thr)
def comps(m):
    seen=np.zeros_like(m,bool); out=[]
    H,W=m.shape
    for y in range(H):
        for x in range(W):
            if m[y,x] and not seen[y,x]:
                q=deque([(y,x)]); seen[y,x]=True; pix=[]
                while q:
                    cy,cx=q.popleft(); pix.append((cy,cx))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
